config.css:
/* ════════ AMOLED BLACK ════════ */
[data-theme="dark"],
[data-theme="light"] {
  color-scheme: dark;

  /* ––– core palette ––– */
  --mp-bg-base: #000000;
  --mp-bg-surface: #000000;
  --mp-bg-elevated: #000000;
  --mp-bg-inset: #000000;
  --mp-chat-bg: #000000;
  --mp-chat-tint: #000000;
  --mp-user-tint: #000000;
  --mp-bot-tint: #000000;

  --mp-text-primary: #f0f0f0;
  --mp-text-secondary: #d45a5a;
  --mp-text-muted: rgba(180, 180, 180, 0.55);
  --mp-text-italics: #d45a5a;
  --mp-text-quote: #d45a5a;
  --mp-text-underline: #d45a5a;
  --mp-text-inverted: #000000;

  --mp-pink: #d45a5a;
  --mp-pink-soft: rgba(212, 90, 90, 0.20);
  --mp-purple: #d45a5a;
  --mp-purple-soft: rgba(212, 90, 90, 0.18);
  --mp-blue: #d45a5a;
  --mp-blue-soft: rgba(212, 90, 90, 0.16);
  --mp-mint: #d45a5a;
  --mp-border: rgba(255, 255, 255, 0.08);
  --mp-shadow: rgba(0, 0, 0, 0.9);

  --mp-rainbow: linear-gradient(90deg, #d45a5a, #b33a3a, #852525);
  --mp-rainbow-vertical: linear-gradient(180deg, #d45a5a, #b33a3a, #852525);

  --background: var(--mp-bg-base);
  --marinara-app-background-paint: var(--mp-bg-base);
  --foreground: var(--mp-text-primary);

  --card: #000000;
  --card-foreground: var(--mp-text-primary);
  --popover: #000000;
  --popover-foreground: var(--mp-text-primary);

  --primary: var(--mp-purple);
  --primary-foreground: var(--mp-text-inverted);

  --secondary: #000000;
  --secondary-foreground: var(--mp-text-primary);

  --muted: #000000;
  --muted-foreground: var(--mp-text-muted);

  --accent: var(--mp-purple-soft);
  --accent-foreground: var(--mp-text-primary);

  --destructive: #e54666;
  --destructive-foreground: #ffffff;

  --border: var(--mp-border);
  --input: var(--mp-border);
  --ring: var(--mp-purple);
  --radius: 1rem;

  --sidebar: #000000;
  --sidebar-foreground: var(--mp-text-primary);
  --sidebar-border: var(--mp-border);
  --sidebar-accent: var(--mp-purple-soft);
  --sidebar-accent-foreground: var(--mp-text-primary);

  --glow-primary: rgba(212, 90, 90, 0.30);
  --glow-accent: rgba(212, 90, 90, 0.30);

  --marinara-app-accent-solid: var(--mp-purple);
  --marinara-app-accent-gradient: #000000;
  --marinara-chat-chrome-accent: var(--mp-purple);
  --marinara-chat-chrome-accent-gradient: #000000;
  --marinara-chat-chrome-text: var(--mp-text-primary);
  --marinara-chat-chrome-panel-muted: rgba(180, 180, 180, 0.45);

  --radius-sm: 10px;
  --radius-md: 16px;
  --radius-lg: 20px;
  --radius-xl: 24px;

  body,
  .app-shell,
  #root,
  #main,
  .main-container,
  .app-background,
  .chat-container,
  .chat-background,
  .message-list,
  .chat-messages,
  .chat-view,
  .conversation-pane,
  .mari-chat-shell,
  .mari-chat-background {
    background-color: var(--background) !important;
    color: var(--foreground) !important;
  }

  ::selection {
    background: rgba(212, 90, 90, 0.35) !important;
    color: #ffffff !important;
  }

  .glass,
  .glass-strong,
  .card,
  .panel,
  .sidebar,
  .drawer,
  .modal-content,
  .settings-section,
  .chat-list,
  .character-card,
  .persona-card {
    background-color: #000000 !important;
    border: 1px solid var(--mp-border) !important;
    border-radius: var(--radius-md) !important;
  }

  .card:hover,
  .character-card:hover,
  .persona-card:hover {
    border-color: var(--mp-purple) !important;
    box-shadow: 0 0 12px var(--glow-primary) !important;
  }

  .menu,
  .dropdown,
  .popover,
  .tooltip,
  .toast {
    background-color: #000000 !important;
    border: 1px solid var(--mp-border) !important;
    box-shadow: 0 0 14px var(--glow-primary) !important;
  }

  .tag,
  .badge {
    background-color: var(--mp-purple-soft) !important;
    color: var(--mp-text-secondary) !important;
    border: 1px solid var(--mp-border) !important;
    border-radius: 999px !important;
    padding: 2px 8px !important;
  }

  hr,
  .divider {
    border-color: var(--mp-border) !important;
  }

  code,
  pre,
  .code-block,
  .mari-message-content .mari-md-inline-code,
  .mari-message-content .mari-md-codeblock {
    background-color: rgba(255, 255, 255, 0.04) !important;
    color: var(--mp-text-secondary) !important;
    border: 1px solid var(--mp-border) !important;
    border-radius: var(--radius-sm) !important;
  }

  h2.mari-chrome-text-strong {
    background: var(--mp-rainbow) !important;
    background-size: 200% auto !important;
    -webkit-background-clip: text !important;
    background-clip: text !important;
    -webkit-text-fill-color: transparent !important;
    color: transparent !important;
    font-weight: 700 !important;
  }

  input,
  textarea,
  select,
  .search-input {
    background-color: rgba(255, 255, 255, 0.04) !important;
    border: 1px solid var(--mp-border) !important;
    border-radius: var(--radius-sm) !important;
    color: var(--mp-text-primary) !important;
  }

  input:focus,
  textarea:focus,
  select:focus {
    outline: none !important;
    border-color: var(--mp-purple) !important;
    box-shadow: 0 0 0 3px rgba(212, 90, 90, 0.20) !important;
  }

  button,
  .btn,
  .action-button {
    background-color: rgba(255, 255, 255, 0.04) !important;
    border: 1px solid var(--mp-border) !important;
    border-radius: var(--radius-sm) !important;
    color: var(--mp-text-primary) !important;
    transition: all 0.3s ease !important;
  }

  button:hover,
  .btn:hover,
  .action-button:hover {
    border-color: var(--mp-purple) !important;
    color: var(--mp-text-secondary) !important;
    box-shadow: 0 0 10px var(--glow-primary) !important;
  }

  button.primary,
  .btn-primary,
  .send-button {
    background: var(--mp-purple) !important;
    color: #ffffff !important;
    border: none !important;
  }

  button.primary:hover,
  .btn-primary:hover,
  .send-button:hover {
    background: #b33a3a !important;
    box-shadow: 0 0 14px var(--glow-accent) !important;
  }

  a,
  .link {
    color: var(--mp-text-secondary) !important;
    text-decoration: none !important;
  }

  a:hover,
  .link:hover {
    color: var(--mp-text-underline) !important;
  }

  #top-bar,
  .top-bar,
  .mari-top-bar {
    height: var(--topBarBlockSize, 48px) !important;
    box-shadow: none !important;
    background: #000000 !important;
    margin-top: 0px !important;
    margin-bottom: 0px !important;
    border-bottom: 1px solid var(--mp-border) !important;
  }

  .mari-topbar-action {
    background: rgba(255, 255, 255, 0.04) !important;
    color: #f0f0f0 !important;
    border: 1px solid var(--mp-border) !important;
    border-radius: 50% !important;
    box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.6) !important;
    transition: all 0.3s ease !important;
  }

  .mari-topbar-action svg,
  .mari-topbar-action .mari-icon,
  .mari-topbar-action i {
    color: #f0f0f0 !important;
    fill: none !important;
    stroke: #f0f0f0 !important;
    stroke-width: 1.5px !important;
  }

  .mari-topbar-action:hover {
    background: rgba(255, 255, 255, 0.08) !important;
    color: #f0f0f0 !important;
    border-color: var(--mp-purple) !important;
    box-shadow: 0 0 12px var(--glow-primary) !important;
  }

  .mari-topbar-action:active {
    transform: scale(0.98) !important;
  }

  .mari-topbar-action[aria-current="page"],
  .mari-topbar-action[aria-selected="true"],
  .mari-topbar-action[data-active="true"],
  .mari-topbar-action.active {
    box-shadow: 0 0 0 2px var(--mp-purple), 0 0.35rem 0.9rem var(--glow-primary) !important;
  }

  .nav-item.active,
  .sidebar-item.active,
  .tab-active {
    background: var(--mp-purple-soft) !important;
    border-left: 3px solid var(--mp-purple) !important;
    color: var(--mp-text-secondary) !important;
  }

  .nav-item:hover,
  .sidebar-item:hover {
    background: rgba(255, 255, 255, 0.04) !important;
  }

  .mari-sidebar-header > div > div:first-child {
    background: rgba(255, 255, 255, 0.04) !important;
    color: #f0f0f0 !important;
    border: 1px solid var(--mp-border) !important;
    box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.6) !important;
    transition: all 0.3s ease !important;
  }

  .mari-sidebar-header > div > div:first-child svg {
    color: #f0f0f0 !important;
    fill: none !important;
    stroke: #f0f0f0 !important;
    stroke-width: 1.5px !important;
  }

  .mari-sidebar-header > div > div:first-child:hover {
    background: rgba(255, 255, 255, 0.08) !important;
    color: #f0f0f0 !important;
    border-color: var(--mp-purple) !important;
    box-shadow: 0 0 12px var(--glow-primary) !important;
  }

  .from-amber-400.to-orange-500,
  [class*="bg-[linear-gradient(135deg,#4de5dd_0%,#eb8951_52%,#e15c8c_100%)]"],
  .from-sky-400.to-blue-500,
  .from-sky-400.to-indigo-500,
  .from-rose-400.to-pink-500,
  .from-emerald-400.to-teal-500,
  .from-gray-400.to-gray-500,
  [class*="4de5dd"],
  .from-violet-400.to-purple-500,
  .from-lime-400.via-green-500.to-cyan-500 {
    box-shadow: none !important;
    background: #000000 !important;
    color: #f0f0f0 !important;
  }

  [class*="persona"] img,
  [class*="persona"] [class*="avatar"],
  [class*="lorebook"] img,
  [class*="lorebook"] [class*="icon"],
  [class*="lorebook"] [class*="avatar"],
  [class*="Lorebook"] img,
  [class*="Lorebook"] [class*="icon"],
  [class*="lorebook-item"] > div:first-child,
  [class*="lorebook-list"] > li > div:first-child {
    border: none !important;
    box-shadow: none !important;
    outline: none !important;
  }

  .mari-avatar-placeholder--persona,
  .mari-editor-avatar-tile.mari-avatar-placeholder--persona,
  .mari-avatar-placeholder--character,
  .mari-editor-avatar-tile.mari-avatar-placeholder--character {
    --mari-avatar-placeholder-start: var(--mp-purple) !important;
    --mari-avatar-placeholder-end: var(--mp-pink) !important;
    --mari-avatar-placeholder-text: #ffffff !important;
    border-radius: 9999px !important;
  }

  .mari-chat-area,
  .mari-messages-scroll,
  .rpg-chat-area,
  .rpg-chat-messages-mobile,
  [data-chat-scroll],
  .chat-background,
  .mari-chat-background {
    background-color: #000000 !important;
    background-image: none !important;
  }

  .texting-bubble-other,
  .glimmer-bubble-char,
  .mari-rp-bubble {
    position: relative !important;
    border-radius: 20px !important;
    padding: 14px 20px 16px 20px !important;
    margin-bottom: 14px !important;
    border: 1px solid rgba(255, 255, 255, 0.06) !important;
    background: rgba(255, 255, 255, 0.02) !important;
    box-shadow: 0 3px 14px rgba(0, 0, 0, 0.8) !important;
  }

  .texting-bubble-user,
  .glimmer-bubble-user {
    position: relative !important;
    border-radius: 20px !important;
    padding: 14px 20px 16px 20px !important;
    margin-bottom: 14px !important;
    border: 1px solid var(--mp-purple) !important;
    background: rgba(212, 90, 90, 0.06) !important;
    box-shadow: 0 3px 14px rgba(0, 0, 0, 0.8) !important;
  }

  .mari-roleplay-message-body.items-end .mari-rp-bubble {
    border: 1px solid var(--mp-purple) !important;
    background: rgba(212, 90, 90, 0.06) !important;
  }

  .texting-bubble-user *,
  .glimmer-bubble-user *,
  .texting-bubble-user .mari-message-content,
  .glimmer-bubble-user .mari-message-content {
    color: var(--mp-text-primary) !important;
    -webkit-text-fill-color: var(--mp-text-primary) !important;
  }

  .glimmer-bubble {
    backdrop-filter: blur(4px);
  }

  .glimmer-streaming {
    animation: glimmer-pulse-prism-dark 2s ease-in-out infinite !important;
  }

  @keyframes glimmer-pulse-prism-dark {
    0%, 100% {
      box-shadow: 0 0 0 2px rgba(212, 90, 90, 0.30), 0 2px 8px rgba(0, 0, 0, 0.8);
    }
    50% {
      box-shadow: 0 0 0 3px rgba(212, 90, 90, 0.50), 0 2px 16px rgba(0, 0, 0, 0.9);
    }
  }

  .mari-message-content,
  .mari-message-content p,
  .mari-message-content span,
  .mari-message-content div {
    color: var(--mp-text-primary) !important;
    text-align: justify !important;
    text-shadow: none !important;
    line-height: 1.8 !important;
    letter-spacing: 0.01em !important;
  }

  .mari-message-content em,
  .mari-message-content i {
    color: var(--mp-text-italics) !important;
  }
  .mari-message-content q,
  .mari-message-content blockquote {
    color: var(--mp-text-quote) !important;
  }
  .mari-message-content u {
    color: var(--mp-text-underline) !important;
  }

  .mari-message-content h1,
  .mari-message-content h2,
  .mari-message-content h3,
  .mari-message-content h4 {
    font-weight: 700 !important;
    color: var(--mp-text-primary) !important;
    background: none !important;
    -webkit-background-clip: unset !important;
    background-clip: unset !important;
    border-radius: 0 !important;
    clip-path: none !important;
    width: auto !important;
    min-width: 0 !important;
    padding: 0 !important;
    margin: 18px 0 8px 0 !important;
    line-height: 1.3 !important;
  }
  .mari-message-content h1 { font-size: 1.75rem !important; }
  .mari-message-content h2 { font-size: 1.4rem !important; }
  .mari-message-content h3 { font-size: 1.15rem !important; }
  .mari-message-content h4 { font-size: 1rem !important; }

  .mari-message-content hr {
    border: none !important;
    height: 2px !important;
    background: var(--mp-border) !important;
    margin: 12px auto !important;
    width: 80% !important;
  }

  .mari-message-timestamp,
  .mari-chat-area .text-\[0\.6875rem\].font-semibold,
  .mari-messages-scroll .text-\[0\.6875rem\].font-semibold,
  [data-chat-scroll] .text-\[0\.6875rem\].font-semibold,
  .mari-chat-area .text-\[var\(--muted-foreground\)\]\/60,
  .mari-messages-scroll .text-\[var\(--muted-foreground\)\]\/60,
  [data-chat-scroll] .text-\[var\(--muted-foreground\)\]\/60,
  .message-timestamp,
  .message-meta,
  .mari-message-meta {
    color: var(--mp-text-muted) !important;
    -webkit-text-fill-color: var(--mp-text-muted) !important;
    opacity: 1 !important;
  }

  .mari-chat-logo-mode--conversation,
  .mari-chat-logo-mode--roleplay,
  .mari-chat-logo-mode--game {
    --mari-chat-logo-mode-color: var(--mp-purple) !important;
    --mari-chat-logo-mode-color-deep: var(--mp-pink) !important;
    --mari-chat-logo-mode-text: #ffffff !important;
  }

  .mari-chat-mode-action {
    background: rgba(255, 255, 255, 0.04) !important;
    color: #f0f0f0 !important;
    border: 1px solid var(--mp-border) !important;
    box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.6) !important;
    text-shadow: 0 1px 4px rgba(0, 0, 0, 0.8) !important;
    transition: all 0.3s ease !important;
  }
  .mari-chat-mode-action:hover,
  .mari-chat-mode-action:focus-visible {
    background: rgba(255, 255, 255, 0.08) !important;
    color: #f0f0f0 !important;
    border-color: var(--mp-purple) !important;
    box-shadow: 0 0.35rem 0.9rem var(--glow-primary) !important;
    transform: translateY(-1px) !important;
  }

  .mari-chat-mode-avatar {
    border: 1px solid color-mix(in srgb, var(--mp-purple) 34%, transparent) !important;
    background: color-mix(in srgb, var(--mp-purple) 16%, #000000 84%) !important;
    color: var(--mp-purple) !important;
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--mp-purple) 18%, transparent) !important;
  }
  .mari-chat-mode-badge {
    background: color-mix(in srgb, var(--mp-purple) 18%, #000000 82%) !important;
    color: var(--mp-purple) !important;
    box-shadow: 0 0 0.45rem color-mix(in srgb, var(--mp-purple) 24%, transparent) !important;
  }

  .mari-chat-input-textarea,
  [class*="leading-tight"][class*="text-foreground"][class*="resize-none"],
  [class*="mari-chat"] textarea {
    font-size: 0.8rem !important;
    line-height: 1.5 !important;
    padding: 0.5rem 0.25rem !important;
    min-height: 2.50rem !important;
    color: var(--foreground) !important;
    background: transparent !important;
  }
  .mari-chat-input-textarea::placeholder,
  [class*="leading-tight"][class*="text-foreground"][class*="resize-none"]::placeholder {
    color: var(--mp-text-muted) !important;
    opacity: 0.6 !important;
  }

  .mari-input-area,
  .mari-send-form,
  #send_form,
  .send-form {
    padding: 4px 0.5% 0 !important;
    border-top: none !important;
    background: #000000 !important;
  }

  .mari-send-form,
  #send_form,
  .send-form {
    border: 1px solid var(--mp-border) !important;
    border-radius: 20px !important;
    background: rgba(255, 255, 255, 0.02) !important;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.8) !important;
  }
  .mari-send-form:focus-within,
  #send_form:focus-within,
  .send-form:focus-within {
    border-color: var(--mp-purple) !important;
    box-shadow: 0 0 0 3px rgba(212, 90, 90, 0.15), 0 2px 12px rgba(0, 0, 0, 0.8) !important;
  }

  .mari-input-area textarea,
  #send_textarea,
  .send-textarea {
    min-height: 60px !important;
    background-color: transparent !important;
    color: var(--mp-text-primary) !important;
    border: none !important;
  }

  .mari-panel-gradient-button[class*="mari-panel-gradient--"],
  .mari-panel-gradient--personas,
  .mari-panel-gradient--characters,
  .mari-panel-gradient--browser,
  .mari-panel-gradient--agents,
  .mari-panel-gradient--presets,
  .mari-panel-gradient--lorebooks,
  .mari-panel-gradient--connections,
  .mari-panel-gradient--extensions,
  .mari-panel-gradient--chats,
  .mari-panel-gradient--settings,
  .mari-panel-gradient--help {
    background: rgba(255, 255, 255, 0.04) !important;
    color: var(--mp-text-primary) !important;
    border: 1px solid var(--mp-border) !important;
    box-shadow: none !important;
  }
  .mari-panel-gradient-button:hover,
  .mari-panel-gradient--personas:hover,
  .mari-panel-gradient--characters:hover,
  .mari-panel-gradient--browser:hover,
  .mari-panel-gradient--agents:hover,
  .mari-panel-gradient--presets:hover,
  .mari-panel-gradient--lorebooks:hover,
  .mari-panel-gradient--connections:hover,
  .mari-panel-gradient--extensions:hover,
  .mari-panel-gradient--chats:hover,
  .mari-panel-gradient--settings:hover,
  .mari-panel-gradient--help:hover {
    background: rgba(255, 255, 255, 0.08) !important;
    border-color: var(--mp-purple) !important;
    box-shadow: 0 0 20px var(--glow-primary) !important;
    transform: scale(1.02) !important;
  }
  .mari-panel-gradient-button[class*="mari-panel-gradient--"].active,
  .mari-panel-gradient-button[class*="mari-panel-gradient--"][data-active="true"],
  .mari-panel-gradient-button[class*="mari-panel-gradient--"][aria-current="page"] {
    box-shadow: 0 0 0 2px var(--mp-purple), 0 0 20px var(--glow-primary) !important;
    background: var(--mp-purple-soft) !important;
    border-color: var(--mp-purple) !important;
  }
  .mari-panel-gradient-button[class*="mari-panel-gradient--"] svg,
  .mari-panel-gradient-button[class*="mari-panel-gradient--"] .mari-icon,
  .mari-panel-gradient-button[class*="mari-panel-gradient--"] i {
    color: #f0f0f0 !important;
    fill: none !important;
    stroke: #f0f0f0 !important;
    stroke-width: 1.5px !important;
  }

  button[aria-pressed="true"][class*="min-h-10"]:not(.mari-topbar-action),
  button[aria-pressed="true"]:not(.mari-topbar-action) {
    border-color: var(--mp-purple) !important;
    background-color: var(--mp-purple-soft) !important;
    color: var(--foreground) !important;
    box-shadow: 0 0 0 1px var(--mp-purple), 0 0 10px var(--glow-primary) !important;
  }

  button[class*="text-[var(--primary)]"][class*="text-[0.625rem]"] {
    border-color: var(--mp-purple) !important;
    background-color: var(--mp-purple-soft) !important;
    color: var(--mp-purple) !important;
    box-shadow: 0 0 0 1px var(--mp-purple) !important;
  }

  ::-webkit-scrollbar {
    width: 10px;
    background: #000000;
  }
  ::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.08);
    border: 2px solid #000000;
    border-radius: 8px;
